(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sk"] = {"ui":{"skip":"Preskočiť na obsah","back":"← Späť na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hľadať jazyky","lang.none":"Žiadny jazyk nezodpovedá","lang.notYet":"{name} ešte nie je preložený","theme.aria":"Prepnúť medzi svetlou a tmavou témou","theme.toLight":"Prepnúť na svetlú tému","theme.toDark":"Prepnúť na tmavú tému","index.title":"AI-gile: tvoj AI vývojársky tím na jednej tabuli","index.description":"AI-gile je kanban tabuľa pre tímy AI programátorov. Pracujú, kým spíš; ty dostaneš jednu krátku kôpku vecí na rozhodnutie, otestovanie a schválenie.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvoj AI vývojársky tím na jednej&nbsp;tabuli.","hero.alpha":"🐣 Uzavretá pre-alfa","hero.alphaTitle":"Skorá a nedokončená verzia: vďaka, že ju skúšaš!","hero.lede":"Stavajú, kým spíš. Ráno ťa čaká jedna krátka kôpka: pár otázok, pár vecí na otestovanie, jeden-dva fialové diamanty. Klikneš, schválíš a vrátiš sa ku káve.","dl.windows":"Aplikácia pre Windows","dl.browser":"Spustiť v prehliadači","dl.soon":"Čoskoro","dl.notify":"🔔 Daj mi vedieť, keď sa otvorí","dl.notifySmall":"Alfa alebo beta","hero.secondary":"Agilne, ale tím nikdy nepotrebuje ranný stand-up s kávou. (Stand-upy aj tak robia.)","pitch.h2":"AI-gile v toľkých slovách, koľko chceš","pitch.lede":"Vyber dĺžku, od jedného slova po 144. Každá dĺžka je samostatný popis napísaný práve pre ňu. Potiahni posuvník alebo použi šípky.","pitch.rangeLabel":"Dĺžka v slovách","pitch.dice":"🎲 iná verzia","pitch.words.one":"{n} slovo","pitch.words.few":"{n} slová","pitch.words.many":"{n} slova","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.few":"{n} písmená","pitch.letters.many":"{n} písmena","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} karta je práve na tabuli","count.line.html.few":"{n} karty sú práve na tabuli","count.line.html.many":"{n} karty je práve na tabuli","count.line.html.other":"{n} kariet je práve na tabuli","features.aria":"Čo robí","f.pile.h":"Jedna kôpka pre teba","f.pile.html":"<b>Pre teba</b> obsahuje všetko, čo čaká na teba, naprieč všetkými projektmi: otázky, veci na otestovanie, úlohy, ktoré zvládne len človek. Tvoj rad ti povie, čo je na rade a koľko to potrvá.","f.sleep.h":"Tímy, ktoré pracujú, kým spíš","f.sleep.p":"Každý projekt má vedúceho a tím AI agentov. Napíš komentár ku karte a tím sa zobudí, odvedie prácu a vráti ti ju s krokmi, ktoré zvládne aj unavený človek.","f.tester.h":"Najprv kontroluje AI tester","f.tester.p":"Skôr než sa čokoľvek dostane k tebe, tester prejde kroky v kópii aplikácie a ukáže, čo videl, so snímkou obrazovky. Prelistuj tie, čo prešli, a schváľ jedným klikom.","f.proof.h":"Dôkazy, nie sľuby","f.proof.p":"Každé odovzdanie ukazuje, čo sa zmenilo: súbory, rozdiely, snímky obrazovky. Nemusíš otvárať každú aplikáciu, aby si zistil, či je hotovo.","f.chat.h":"Chat so svojimi vedúcimi","f.chat.p":"Lišta ako na Discorde: jedna ikona na projekt, fialové diamanty pri tom, čo potrebuje teba. Napíš vedúcemu nápad; premení ho na karty a plán s tlačidlom ✅ Ísť na to.","f.tidy.h":"Upratuje si po sebe","f.tidy.p":"Súvisiace karty sa zlúčia, zmätené názvy sa opravia a kontrola tokenov udržiava kód štíhly. Menej vecí na prepínanie, menej na premýšľanie.","f.private.h":"Tvoje, na tvojom počítači","f.private.li1":"Tabuľa beží na tvojom vlastnom stroji a odpovedá len tebe.","f.private.li2":"Súkromné správy medzi ľuďmi sú šifrované end-to-end.","f.private.li3":"Žiadne účty, žiadne sledovače, žiadne cookies.","f.lang.h":"Vo tvojom jazyku","f.lang.p":"Vyše 120 jazykov, od holandčiny, walesčiny a japončiny až po pirátčinu, Yodu a klingončinu, s rýchlym prepnutím späť do angličtiny pre vývojárske slová.","tl.aria":"Časová os od prvého rozhovoru po plán","tl.h2":"Od prvého rozhovoru po to, čo príde","tl.lede":"Skutočné dátumy a časy vo tvojom časovom pásme. Po dnešku je to plán, bez sľubovaných dátumov.","tl.today":"Dnes","tl.planned":"plánované","tl.cards.one":"{n} karta","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty","tl.cards.other":"{n} kariet","join.h2":"Pridaj sa","join.lede":"AI-gile stavia jeden malý človek a veľa trpezlivých agentov. Zatiaľ je súkromné, v uzavretej alfe s priateľmi. Chceš si ho vyskúšať, keď sa otvorí?","join.btn":"Prejaviť záujem","join.small":"Napíšeme ti e-mail, nič iné","footer.tag":"AI-gile. Žiadne sledovače, žiadne cookies, žiadna stand-up káva.","footer.licence":"Podniková licencia","footer.status":"Stav","form.sending":"Odosiela sa…","form.failed":"Nevyšlo to: skús to neskôr.","form.offline":"AI-gile sa nepodarilo kontaktovať: skús to neskôr.","interest.title":"AI-gile: daj mi vedieť, keď sa otvorí alfa","interest.description":"Nechaj nám e-mail a dáme ti vedieť, keď sa otvorí uzavretá alfa alebo beta AI-gile.","interest.h1":"🔔 Daj mi vedieť, keď sa otvorí","interest.lede":"AI-gile je v uzavretej pre-alfe. Nechaj nám e-mail a napíšeme ti raz, keď bude pre teba miesto.","interest.email":"Tvoj e-mail","interest.which":"Ktorý test?","interest.alpha":"Uzavretá alfa: skorá, drsná, veľa zmien","interest.beta":"Beta: stabilnejšia, neskôr","interest.both":"Ktorýkoľvek, podľa toho, čo bude skôr","interest.submit":"Zapísať ma do zoznamu","interest.thanks":"Vďaka! Si v zozname.","interest.kept":"Uchovávame len tvoj e-mail a vybraný test, výlučne pre tento zoznam. Žiadny newsletter, žiadne sledovače.","licence.title":"AI-gile: podniková licencia","licence.description":"Používaš AI-gile vo svojej firme? Požiadaj o bezplatnú podnikovú licenciu.","licence.h1":"📜 Podniková licencia","licence.lede":"Používaš AI-gile v práci? Povedz nám, kto si a čo robíš. Ak to robí svet lepším, licencia je zadarmo.","licence.company":"Firma","licence.website":"Web","licence.what":"Čo robíš","licence.how":"Ako to pomáha svetu","licence.email":"E-mail","licence.submit":"Požiadať","licence.thanks":"Vďaka! Odpovieme e-mailom.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Všetko pokojné","status.checking":"Kontroluje sa…","status.offline":"Služba stavu je teraz nedostupná (skúšam znova)","status.updated":"aktualizované {ago}","status.justNow":"práve teraz","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","live.h2":"Sledujte, ako sa to stavia, naživo","live.caption":"Každá karta je skrytá: vidíte tvar práce, nie slová.","live.watching.one":"naživo: sleduje {n}","live.watching.other":"naživo: sledujú {n}","live.offline":"Živá tabuľa si dáva pauzu. Skúste to čoskoro znova.","live.cols":"Backlog|Na urobenie|Rozrobené|Tím kontroluje|Čaká na tvoj test|Pre tím|Hotovo"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegované."]},{"n":2,"texts":["Robotický kanban.","Agenti, usporiadaní.","Nápady hotovo."]},{"n":3,"texts":["Kanban pre robotov.","Z nápadov funkcie.","Bezplatný kanban agentov."]},{"n":5,"texts":["Kanban tabuľa, ktorú vedú agenti.","Ty píšeš karty. Agenti staviajú.","Zadarmo, lokálne, testované, trochu bláznivé."]},{"n":8,"texts":["Bezplatná kanban tabuľa, na ktorej pracujú AI agenti.","Napíš nápad. Agenti ho postavia. Ty ho schváliš.","Agilita pre jedného človeka a veľa trpezlivých robotov."]},{"n":13,"texts":["Kanban tabuľa na tvojom počítači, kde si karty preberajú AI agenti a pracujú na nich.","Napíš nápad. Tím agentov ho postaví. Tester ho skontroluje. Ty povieš áno.","Zadarmo, bez účtov a sledovačov: tabuľa, zopár robotov a ty ako šéf."]},{"n":21,"texts":["AI-gile je kanban tabuľa na prácu s AI agentmi, ktorí programujú. Oni preberajú karty a ty ich testuješ a schvaľuješ.","Každý projekt dostane vedúceho a tím AI agentov. Napíš komentár k ľubovoľnej karte a tím sa pustí do práce.","Bezplatná osobná tabuľa úloh, ktorá beží na tvojom vlastnom počítači. Pracujú na nej roboti. Povedať áno môžeš len ty."]},{"n":34,"texts":["Nápady dáš na tabuľu. Tím AI agentov ich premení na fungujúce funkcie, otestuje ich a vráti ti ich s krokmi na vyskúšanie. Nič nie je hotové, kým to nepovieš ty.","AI-gile je domáca kanban tabuľa, ktorú Rich postavil s veľkou pomocou agentov, ktorých dnes sama riadi. Je zadarmo, beží na tvojom počítači a zdieľa sa s priateľmi, nepredáva sa.","Predstav si obyčajnú kanban tabuľu so stĺpcami od Backlogu po Hotovo, len karty preberajú AI agenti. Hlásia pokrok, pýtajú sa, keď uviaznu, a vždy počkajú na tvoj súhlas."]},{"n":55,"texts":["AI-gile je kanban tabuľa, kde tím tvoria AI agenti. Každý projekt má vedúceho, ktorý plánuje prácu, a pomocníkov, ktorí ju stavajú. Keď je funkcia hotová, AI tester ju vyskúša a urobí snímku obrazovky, potom pristane na tvojej kôpke. Schváľ ju, alebo napíš komentár a prepracujú ju.","Začalo to ako spôsob, ako si jeden človek stráži veľa AI programátorských relácií naraz, a vyrástla z toho poriadna tabuľa. Beží na tvojom stroji, nepotrebuje účet a nemá sledovače. Pre priateľov a zvedavcov je zadarmo. Je aj nedokončená, takže počítaj s hranami a občasným prekvapením.","Tu je úprimná verzia. Nápady musíš stále mať ty a výsledky musíš stále skontrolovať ty. AI-gile robí všetko, čo je medzi tým: drží karty v poriadku, zobudí správneho agenta, keď napíšeš komentár, presne ukáže, čo sa zmenilo, a všetko ti zloží do jednej krátkej kôpky, ktorú zvládneš prejsť aj pri raňajšej káve."]},{"n":89,"texts":["AI-gile je bezplatná kanban tabuľa, ktorú spúšťaš na vlastnom počítači. Namiesto ľudí má každý projekt tím AI agentov: vedúceho, ktorý tvoje nápady premení na karty a plán, a pomocníkov, ktorí karty preberajú podľa priority. Keď je niečo postavené, AI tester prejde testovacie kroky a ukáže ti, čo videl. Potom to čaká v jednej kôpke s názvom Pre teba. Schválíš to, alebo napíšeš komentár a tím to skúsi znova. Do stĺpca Hotovo sa nič nedostane bez teba.","Niekoľko vecí, ktoré by ťa mohli prekvapiť. Nočná hliadka dopĺňa stĺpec Na urobenie, kým spíš, a vyberá karty, ktoré od teba nepotrebujú odpoveď. Počítadlo tokenov ukazuje, koľko agenti minuli dnes a tento týždeň, a Režim bez tokenov im povie, aby prestali míňať. S priateľmi si môžeš písať a súkromné správy sú šifrované end-to-end. Tabuľa hovorí približne 120 jazykmi, aj holandsky, flámsky, pirátsky a klingonsky. Nič z toho nestojí ani cent a nikto sa ti to ani nesnaží predať.","AI-gile je malý osobný projekt, nie firma. Rich chcel spravovať niekoľko AI programátorských projektov bez otvárania každej aplikácie, tak spolu s agentmi postavil tabuľu a potom na nej postavil zvyšok seba samej. Je v uzavretej pre-alfe, čo znamená, že pre hŕstku priateľov funguje, väčšinou. Nemá cenník, newsletter ani plán rastu. Beží na tvojom počítači, bez účtov a bez sledovačov. Ak ti to znie užitočne, môžeš si vyžiadať vyskúšanie, keď sa trochu viac otvorí. Napíšeme ti jediný e-mail, nič iné."]},{"n":144,"texts":["AI-gile je kanban tabuľa pre jedného človeka a veľa AI agentov. Beží na tvojom vlastnom počítači a je úplne zadarmo. Pridáš projekty a každý dostane vedúceho a malý tím. S vedúcim chatuješ, trochu ako na Discorde, a opíšeš nápad; vedúci z neho spraví karty a plán a potom čaká, kým stlačíš Ísť na to. Tím prechádza karty podľa priority pomocou jednoduchého príkazového riadku vytvoreného pre jazykové modely. Skôr než sa čokoľvek vráti k tebe, AI tester prejde kroky v kópii aplikácie a priloží snímku obrazovky. Hotová práca pristane na tvojej kôpke so zmenenými súbormi a rozdielmi. Schválíš ju, alebo zanecháš komentár a tím sa zobudí a skúsi to znova. Kartu do Hotovo môžeš presunúť len ty.","Deň s AI-gile, zhruba. Večer necháš pár komentárov: toto tlačidlo je na zlom mieste, ten zoznam by mal byť zoradený, mohli by sme mať tmavý režim. Ideš spať. Agenti si prečítajú komentáre, urobia zmeny, otestujú ich a vrátia ti ich. Ak Na urobenie vyschne, nočná hliadka ho doplní z backlogu kartami, ktoré od teba nepotrebujú odpoveď. Ráno je tu jedna krátka kôpka: pár otázok a zopár vecí na vyskúšanie, každá s krokmi, ktoré zvládne aj rozospatý človek, a so snímkou, že to funguje. Prekliknieš sa, schváliš dobré a zvyšok pošleš späť. Počítadlo tokenov ukáže, čo to všetko stálo, a Režim bez tokenov je tu na skromnejšie týždne. Potom si dáš raňajky, v ktorých ti agenti zatiaľ pomôcť nevedia.","Najprv to, čo AI-gile nie je. Nie je to startup, nie je na predaj a nikto nezbiera tvoje dáta. Je to bezplatná tabuľa, ktorá beží na tvojom počítači, bez účtov, bez sledovačov a bez cookies. A čo to je: jedno prehľadné miesto, kde vidíš všetky AI programátorské projekty naraz, s tímom agentov, ktorý robí karty, a tebou, ktorý rozhoduješ. Zlučuje súvisiace karty, opravuje zmätené názvy a pozerá, aby kód zostal štíhly. Hovorí približne 120 jazykmi, od holandčiny a flámčiny po pirátčinu a klingončinu. Priatelia si môžu písať súkromne a šifrovane. Postavil ho Rich s veľkým počtom trpezlivých agentov, väčšinou za pomoci seba samého. Je v uzavretej pre-alfe, takže miestami drhne. Ak ti to znie zábavne, pekne požiadaj a možno sa dostaneš dnu skôr."]}],"quips":{"1":"Jedno slovo. Odvážne. Možno príliš.","3":"Tri slová. Už teraz úprimnejšie ako väčšina produktových stránok.","8":"Osem slov. Stále kratšie ako stand-up.","21":"Dĺžky sú mimochodom story pointy. Samozrejme, že sú.","55":"Päťdesiatpäť slov. Kým si to čítal, dokončili sa dve karty.","144":"To je tá dlhá. 233 neexistuje. Agenti išli spať."}},"timeline":{"first-idea.name":"Prvý nápad","first-idea.line":"Úplne prvý rozhovor, ešte pred prvým riadkom kódu.","first-board.name":"Prvá tabuľa","first-board.line":"Tabuľa, ktorá sleduje vlastnú stavbu: karty, stĺpce, presúvanie, projekty.","team-roles.name":"Tím a roly","team-roles.line":"Profily agentov, šablóny tímov, priestory a kto robí čo.","install.name":"Inštalácia a vydania","install.line":"Zip, ktorý si nainštaluje aj kamarát, samoaktualizácie, kanály a návrat späť.","usage-saver.name":"Šetrič spotreby","usage-saver.line":"Zmeraj, koľko behy stoja, udržuj kód štíhly, šetri svoj limit.","friends.name":"Priatelia a zdieľanie","friends.line":"Súkromné správy, šifrované relé, pozvánky, roly a zdieľané projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovom súbore, najprv holandčina a flámčina.","ai-tester.name":"AI tester","ai-tester.line":"Tester najprv skontroluje každé odovzdanie a ukáže, čo videl.","website.name":"Web","website.line":"aigile.lol, ukážka a táto časová os.","streaming.name":"Chat a streamovanie","streaming.line":"Discord, Twitch, OBS, režim streamera, GIFy a emoji.","no-ai.name":"Edícia bez AI","no-ai.line":"Tabuľa pre ľudí, ktorí programujú bez AI, a verejné tabule.","night-watch.name":"Nočná hliadka","night-watch.line":"Strážca a Scrum Master držia tímy pri práci, kým spíš.","p-more.name":"Všetko ostatné","p-more.line":"Menšie nápady, ktoré čakajú na rad.","p-android.name":"Telefón a Android","p-android.line":"Tabuľa z telefónu a potom natívna aplikácia pre Android.","p-release.name":"Alfa a ďalej","p-release.line":"Uzavretá alfa, živý web a potom beta.","p-languages.name":"Viac jazykov","p-languages.line":"Viac než sto jazykov a imerzný režim pre študentov.","p-engines.name":"Viac AI motorov","p-engines.line":"Vyber Claude, Codex alebo Gemini pre každého agenta.","p-pro.name":"Profesionálna prax","p-pro.line":"Štítky rizika, brány zlúčenia, karty incidentov a zábradlia.","p-self.name":"Starostlivosť o teba","p-self.line":"Režim únavy, pripomienky starostlivosti o seba a 4:20.","p-servers.name":"Servery a rast","p-servers.line":"Globálne nastavenia servera, roly a plánovanie rastu.","p-livestream.name":"Streamovacie doplnky","p-livestream.line":"Twitch chat, vlastné emoji a verejný živý pohľad."}};
